-- Organizations, billing entities and invoice custom sections (domain §4,
-- §11.9), and the infrastructure tables of the store: counters (port.Sequences)
-- and the job outbox (port.JobEnqueuer).
--
-- Conventions of every schema file (docs/architecture.md §5):
--   * Files are applied in name order; a table references only tables of
--     earlier files. A foreign key to a later file's table is added by an
--     ALTER TABLE in a 90_fk_<area>.sql file.
--   * Business tables have organization_id; the primary key is
--     (organization_id, id), ids are UUIDv7 generated by the application.
--     References to rows of the same organization are composite foreign keys
--     (organization_id, x_id) → (organization_id, id), so a row can never
--     point at another organization's row.
--   * Money in minor units is bigint; precise amounts, prices and quantities
--     are numeric; instants are timestamptz (UTC); enumerations are text
--     with a CHECK listing the values of the Go type; lists of enumeration
--     values are text[] with a CHECK (… <@ ARRAY[…]).
--   * Client-supplied JSON documents kept verbatim are json (byte-exact);
--     store-encoded value objects and metadata are jsonb.
--   * Uniqueness among live rows (codes, external IDs) is a partial unique
--     index.
--   * Every table with organization_id enables row-level security with the
--     policy tenant_isolation (see package store's documentation).

CREATE TABLE organizations (
  id uuid NOT NULL,
  name text NOT NULL,
  slug text NOT NULL,
  email text,
  logo text,
  address_line1 text NOT NULL DEFAULT '',
  address_line2 text NOT NULL DEFAULT '',
  address_city text NOT NULL DEFAULT '',
  address_state text NOT NULL DEFAULT '',
  address_zipcode text NOT NULL DEFAULT '',
  address_country text NOT NULL DEFAULT '',
  authentication_methods text[] NOT NULL,
  from_email_enabled boolean NOT NULL DEFAULT false,
  audit_logs_retention_days integer NOT NULL,
  max_wallets_per_customer integer NOT NULL,
  document_number_prefix text NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT organizations_slug_key UNIQUE (slug),
  CONSTRAINT organizations_authentication_methods_check CHECK (authentication_methods <@ ARRAY['email_password', 'google_oauth', 'okta', 'entra_id', 'oidc']::text[]),
  CONSTRAINT organizations_audit_logs_retention_days_check CHECK (audit_logs_retention_days > 0),
  CONSTRAINT organizations_max_wallets_per_customer_check CHECK (max_wallets_per_customer > 0),
  CONSTRAINT organizations_document_number_prefix_check CHECK (char_length(document_number_prefix) BETWEEN 1 AND 10)
);

ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON organizations
  USING (id = NULLIF(NULLIF(current_setting('tanvo.organization_id', true), ''), '*')::uuid OR current_setting('tanvo.organization_id', true) = '*');

CREATE TABLE billing_entities (
  organization_id uuid NOT NULL,
  id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  legal_name text,
  legal_number text,
  tax_id text,
  email text,
  phone text,
  address_line1 text NOT NULL DEFAULT '',
  address_line2 text NOT NULL DEFAULT '',
  address_city text NOT NULL DEFAULT '',
  address_state text NOT NULL DEFAULT '',
  address_zipcode text NOT NULL DEFAULT '',
  address_country text NOT NULL DEFAULT '',
  logo text,
  timezone text,
  default_currency text,
  document_locale text NOT NULL,
  document_numbering text NOT NULL,
  document_number_prefix text NOT NULL,
  invoice_footer text,
  invoice_grace_period_days integer NOT NULL DEFAULT 0,
  net_payment_term_days integer NOT NULL DEFAULT 0,
  finalize_zero_amount_invoice boolean NOT NULL,
  skip_credit_invoice_payment_delay boolean NOT NULL DEFAULT false,
  issuing_date_anchor text NOT NULL,
  issuing_date_adjustment text NOT NULL,
  email_settings text[] NOT NULL DEFAULT '{}',
  eu_tax_management boolean NOT NULL DEFAULT false,
  einvoicing boolean NOT NULL DEFAULT false,
  is_default boolean NOT NULL DEFAULT false,
  -- References dunning_campaigns; the foreign key is added in 09_dunning.sql.
  applied_dunning_campaign_id uuid,
  archived_at timestamptz,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  PRIMARY KEY (organization_id, id),
  CONSTRAINT billing_entities_organization_fkey FOREIGN KEY (organization_id) REFERENCES organizations (id),
  CONSTRAINT billing_entities_document_numbering_check CHECK (document_numbering IN ('per_customer', 'per_billing_entity')),
  CONSTRAINT billing_entities_issuing_date_anchor_check CHECK (issuing_date_anchor IN ('current_period_end', 'next_period_start')),
  CONSTRAINT billing_entities_issuing_date_adjustment_check CHECK (issuing_date_adjustment IN ('keep_anchor', 'align_with_finalization_date')),
  CONSTRAINT billing_entities_email_settings_check CHECK (email_settings <@ ARRAY['invoice.finalized', 'credit_note.created', 'payment_receipt.created']::text[]),
  CONSTRAINT billing_entities_invoice_grace_period_days_check CHECK (invoice_grace_period_days >= 0),
  CONSTRAINT billing_entities_net_payment_term_days_check CHECK (net_payment_term_days >= 0)
);

-- Codes are unique among non-archived entities; at most one default entity.
CREATE UNIQUE INDEX billing_entities_code_live_key ON billing_entities (organization_id, code) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX billing_entities_default_key ON billing_entities (organization_id) WHERE is_default;

ALTER TABLE billing_entities ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON billing_entities
  USING (organization_id = NULLIF(NULLIF(current_setting('tanvo.organization_id', true), ''), '*')::uuid OR current_setting('tanvo.organization_id', true) = '*');

CREATE TABLE invoice_custom_sections (
  organization_id uuid NOT NULL,
  id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  display_name text,
  details text,
  description text,
  section_type text NOT NULL,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  PRIMARY KEY (organization_id, id),
  CONSTRAINT invoice_custom_sections_organization_fkey FOREIGN KEY (organization_id) REFERENCES organizations (id),
  CONSTRAINT invoice_custom_sections_section_type_check CHECK (section_type IN ('manual', 'system_generated'))
);

-- Codes are unique among live sections; deleted ones are kept.
CREATE UNIQUE INDEX invoice_custom_sections_code_key ON invoice_custom_sections (organization_id, code) WHERE deleted_at IS NULL;

ALTER TABLE invoice_custom_sections ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON invoice_custom_sections
  USING (organization_id = NULLIF(NULLIF(current_setting('tanvo.organization_id', true), ''), '*')::uuid OR current_setting('tanvo.organization_id', true) = '*');

-- Gapless counters of port.Sequences: the row of a counter is locked by the
-- increment until the transaction ends, so numbers are never skipped and a
-- rolled-back number is handed out again. scope is the counted-for object,
-- or the nil UUID for organization-wide counters.
CREATE TABLE counters (
  organization_id uuid NOT NULL,
  name text NOT NULL,
  scope uuid NOT NULL,
  value bigint NOT NULL,
  PRIMARY KEY (organization_id, name, scope),
  CONSTRAINT counters_organization_fkey FOREIGN KEY (organization_id) REFERENCES organizations (id),
  CONSTRAINT counters_name_check CHECK (name <> ''),
  CONSTRAINT counters_value_check CHECK (value > 0)
);

ALTER TABLE counters ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON counters
  USING (organization_id = NULLIF(NULLIF(current_setting('tanvo.organization_id', true), ''), '*')::uuid OR current_setting('tanvo.organization_id', true) = '*');

-- Transactional outbox of port.JobEnqueuer: jobs are inserted in the
-- enqueuing transaction and moved to the job queue (River, libs/jobs) by a
-- relay after commit. The relay works across organizations, so the outbox
-- has no row-level security. A unique key is unique per kind among the jobs
-- still in the outbox; past the relay, the queue's own uniqueness applies.
CREATE TABLE job_outbox (
  id bigint GENERATED ALWAYS AS IDENTITY,
  organization_id uuid NOT NULL,
  kind text NOT NULL,
  queue text NOT NULL,
  args json,
  run_at timestamptz,
  unique_key text,
  max_attempts integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT job_outbox_kind_check CHECK (kind <> ''),
  CONSTRAINT job_outbox_queue_check CHECK (queue IN ('billing', 'payments', 'webhooks', 'documents', 'integrations', 'exports', 'alerts', 'alerts_high_priority', 'wallets', 'default')),
  CONSTRAINT job_outbox_max_attempts_check CHECK (max_attempts >= 0)
);

CREATE UNIQUE INDEX job_outbox_unique_key ON job_outbox (organization_id, kind, unique_key) WHERE unique_key IS NOT NULL;

-- Leases of the concurrency slots of port.Slots (Store.AcquireSlot): row
-- (name, slot) is slot number slot of the limit slots named name, held by
-- holder, a random token, until expires_at (the database clock). The names
-- are shared by every process and are not an organization's rows (a name
-- may embed an organization's ID), so the table has neither
-- organization_id nor row-level security. A released lease is deleted;
-- the lease of a crashed holder expires and is overwritten by the next
-- acquirer, so no job cleans the table.
CREATE TABLE concurrency_slots (
  name text NOT NULL,
  slot integer NOT NULL,
  holder uuid NOT NULL,
  expires_at timestamptz NOT NULL,
  PRIMARY KEY (name, slot),
  CONSTRAINT concurrency_slots_name_check CHECK (name <> ''),
  CONSTRAINT concurrency_slots_slot_check CHECK (slot >= 0)
);
